{
  "participants": [
    {
      "login": "maflcko",
      "stance": "objection",
      "note": "concerned about flattening errors back down and RPC consistency, settled by FatalError type"
    },
    {
      "login": "optout21",
      "stance": "objection",
      "note": "Concept ACK, but raised concerns over suppressed BlockChecked signals and miner error changes"
    },
    {
      "login": "hodlinator",
      "stance": "support",
      "note": "Concept ACK on extracting errors via util::Expected; suggested splitting commits"
    }
  ],
  "claims": [
    {
      "id": "c:4912465662",
      "kind": "interface",
      "harm": "Separating errors causes inconsistent RPC error mapping and redundant complexity if errors are immediately flattened back down to booleans.",
      "quote": "Either we can distinguish the two cases clearly, in which case a separate type and handling makes sense (and they shouldn't be flattened down). Or, we can not distinguish them, in which case splitting them up and then flattening them down again seems pointless?",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:4988444254"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:4988444254",
      "settled_by_quote": "Fatal/system failures are now represented separately as kernel::FatalError and propagated via util::Expected, while BlockValidationState now only represents valid vs. invalid consensus validation. Also, the existing RPC behavior is preserved."
    },
    {
      "id": "rc:3959411618",
      "kind": "correctness",
      "harm": "Omitting the BlockChecked callback in error paths changes validation notification behavior for interface consumers.",
      "quote": "I think there is a behavior change here in case of Error: previously `BlockChecked` was called, and now it isn't.",
      "blocking": false,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    },
    {
      "id": "rc:3959219381",
      "kind": "correctness",
      "harm": "May alter miner error handling where error cases previously mapped to inconclusive.",
      "quote": "It's not clear to me that this does not introduce new error reasons. I have the impression that the Error case previously resulted in \"inconclusive\" (but I'm not sure). If that's the case, this needs to be changed.",
      "blocking": false,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    }
  ],
  "support": [
    {
      "id": "r:4650703493",
      "verdict": "Concept ACK",
      "reason": "enforcement of returned errors -- some methods can return only runtime errors; reduced risk of accidental mix-up of validation and runtime errors.",
      "substantive": true
    },
    {
      "id": "r:5141537388",
      "verdict": "Concept ACK",
      "reason": "PR stands on its own and complements #35570 by cleanly separating runtime errors.",
      "substantive": true
    },
    {
      "id": "r:5210572199",
      "verdict": "Concept ACK",
      "reason": "Extracting the error-part of BlockValidationState by using util::Expected is a promising direction.",
      "substantive": true
    }
  ],
  "notes": "maflcko's concern about flattening errors and RPC mapping was resolved by introducing kernel::FatalError. optout21's warnings about omitted BlockChecked signals and miner return behavior remain open without author reply. Requests by optout21 and hodlinator to break up the large commit into smaller pieces were excluded as commit structure issues per rules."
}
